#!/usr/bin/python3
"""Prepare an encrypted candidate from verified legacy history; do not change product state."""
import datetime,json,os,pathlib,socket,subprocess
assert os.geteuid()==0 and socket.gethostname()=='hermes-home'
root=pathlib.Path('/data/hermes/himawari')
output=root/'qualifications/2026-09-11-protected/attempt-v5/native-history-candidate-qualification-v2.json'
assert output.parent.resolve()==output.parent and output.parent.stat().st_uid==0
assert not output.exists(),'Diagnostic already exists; do not repeat'
NODE_SOURCE = 'import assert from \'node:assert/strict\';\nimport { readFile } from \'node:fs/promises\';\nimport { createRequire } from \'node:module\';\nconst root=\'/data/hermes/himawari\';\nconst runtime=root+\'/releases/2026-09-11-control-center/lib/himawari-agent\';\nconst require=createRequire(runtime+\'/package.json\');\nconst {EnvelopePayloadProtector,SystemdCredentialSecretSource}=require(\'@himawari-agent/platform-node\');\nconst Database=require(\'better-sqlite3\');\nconst config=JSON.parse(await readFile(root+\'/config/production.json\',\'utf8\'));\nassert.equal(config.stateRoot,root+\'/state\');\nconst key=config.secretReferences.filter(x=>x.purpose===\'payload-encryption\');\nassert.equal(key.length,1);\nconst protector=new EnvelopePayloadProtector({keys:new SystemdCredentialSecretSource(root+\'/state/secrets\'),activeKey:{keyRef:key[0].ref,kekVersion:key[0].version,dekVersion:\'dek-v1\'}});\nconst db=new Database(root+\'/state/data/product.sqlite\',{readonly:true,fileMustExist:true});\ndb.pragma(\'query_only = ON\');\nasync function payload(ref){\n const row=db.prepare("SELECT * FROM payloads WHERE ref=? AND owner_id=? AND agent_id=? AND lifecycle_state=\'active\'").get(ref,config.ownerId,config.agentId);\n assert(row,\'PAYLOAD_MISSING\');assert.equal(row.storage_kind,\'sqlite_blob\');\n const bytes=await protector.unprotect({ownerId:row.owner_id,agentId:row.agent_id,payload:{ref:row.ref,dataClassification:row.classification,contentType:row.content_type,ciphertext:row.ciphertext,encryption:JSON.parse(row.encryption_metadata_json),contentDigest:row.content_digest,createdAt:row.created_at,storage:{kind:\'inline\'}}});\n const text=new TextDecoder().decode(bytes);\n return row.content_type===\'application/json\'?JSON.parse(text):text;\n}\n\n\nconst pin=JSON.parse(await readFile(runtime+"/node_modules/@earendil-works/pi-ai/package.json","utf8"));\nassert.equal(pin.version,"0.84.2","AUDIT_PI_VERSION");\nconst {convertToLlm}=await import(runtime+"/node_modules/@earendil-works/pi-coding-agent/dist/index.js");\nfunction record(value) {\n    return value !== null && typeof value === "object" && !Array.isArray(value);\n}\nfunction content(value, allowed, text = false) {\n    return ((text && typeof value === "string") ||\n        (Array.isArray(value) &&\n            value.every((block) => record(block) &&\n                allowed.includes(String(block["type"])) &&\n                ((block["type"] === "text" && typeof block["text"] === "string") ||\n                    (block["type"] === "thinking" && typeof block["thinking"] === "string") ||\n                    (block["type"] === "image" &&\n                        typeof block["data"] === "string" &&\n                        typeof block["mimeType"] === "string") ||\n                    (block["type"] === "toolCall" &&\n                        typeof block["id"] === "string" &&\n                        typeof block["name"] === "string" &&\n                        record(block["arguments"]))))));\n}\n/** Validate protected native bytes once at the Pi boundary, then use Pi\'s own conversion. */\nexport function nativeHistoryMessages(values) {\n    const native = [];\n    for (const item of values) {\n        if (!record(item) ||\n            typeof item["timestamp"] !== "number" ||\n            !Number.isFinite(item["timestamp"]))\n            throw new Error("PI_HISTORY_MESSAGE_INVALID");\n        const role = item["role"];\n        const valid = (role === "user" && content(item["content"], ["text", "image"], true)) ||\n            (role === "assistant" &&\n                Array.isArray(item["content"]) &&\n                content(item["content"], ["text", "thinking", "toolCall"]) &&\n                ["provider", "api", "model", "stopReason"].every((key) => typeof item[key] === "string") &&\n                ["stop", "length", "toolUse", "error", "aborted", "deferred"].includes(String(item["stopReason"])) &&\n                record(item["usage"])) ||\n            (role === "toolResult" &&\n                content(item["content"], ["text", "image"]) &&\n                typeof item["toolCallId"] === "string" &&\n                typeof item["toolName"] === "string" &&\n                typeof item["isError"] === "boolean") ||\n            (role === "custom" &&\n                typeof item["customType"] === "string" &&\n                content(item["content"], ["text", "image"], true)) ||\n            (role === "compactionSummary" &&\n                typeof item["summary"] === "string" &&\n                typeof item["tokensBefore"] === "number") ||\n            (role === "branchSummary" &&\n                typeof item["summary"] === "string" &&\n                typeof item["fromId"] === "string");\n        if (!valid)\n            throw new Error("PI_HISTORY_MESSAGE_INVALID");\n        // Product context is refreshed for this Run; do not duplicate stale memory/worker blocks.\n        if (role === "custom" && item["customType"] === "himawari.context.block")\n            continue;\n        native.push(structuredClone(item));\n    }\n    return convertToLlm(native);\n}\nfunction legacyRecord(value) {\n    return value !== null && typeof value === "object" && !Array.isArray(value);\n}\n/** One-time qualification of verified legacy observations; never used for normal Run replay. */\nexport function qualifyLegacyPiHistory(runs) {\n    const messages = [], coveredRunIds = [];\n    const incompleteCancelledRuns = [];\n    let duplicateMessages = 0, repairedUsageTotals = 0;\n    for (const run of runs) {\n        if (coveredRunIds.includes(run.runId))\n            throw new Error("LEGACY_HISTORY_DUPLICATE_RUN");\n        const seen = new Set(), pending = new Map(), called = new Set();\n        let endedAssistant = false, userCount = 0, timestamp = 0;\n        for (const source of run.finalizedMessages) {\n            const identity = JSON.stringify(source);\n            if (seen.has(identity)) {\n                duplicateMessages++;\n                continue;\n            }\n            seen.add(identity);\n            const message = structuredClone(source);\n            if (!legacyRecord(message) ||\n                !["user", "assistant", "toolResult"].includes(String(message["role"])))\n                throw new Error("LEGACY_HISTORY_MESSAGE_INVALID");\n            const usage = message["usage"];\n            // Pi 0.84.2 OpenAI-completions defines this total as the sum of these four fields.\n            // Legacy observer redaction matched "totalTokens" even though it was not a secret.\n            if (message["role"] === "assistant" &&\n                message["api"] === "openai-completions" &&\n                legacyRecord(usage) &&\n                usage["totalTokens"] === "[REDACTED]" &&\n                ["input", "output", "cacheRead", "cacheWrite"].every((key) => typeof usage[key] === "number" && Number.isFinite(usage[key]) && usage[key] >= 0)) {\n                usage["totalTokens"] = ["input", "output", "cacheRead", "cacheWrite"].reduce((sum, key) => sum + usage[key], 0);\n                repairedUsageTotals++;\n            }\n            if (JSON.stringify(message).includes("[REDACTED") ||\n                JSON.stringify(message).includes("RUNTIME_TOOL_SUSPENDED"))\n                throw new Error("LEGACY_HISTORY_CONTENT_UNAVAILABLE");\n            const native = nativeHistoryMessages([message])[0];\n            if (!native || !["user", "assistant", "toolResult"].includes(native.role))\n                throw new Error("LEGACY_HISTORY_MESSAGE_INVALID");\n            timestamp = Math.max(timestamp, native.timestamp);\n            if (native.role === "user") {\n                if (++userCount !== 1 || seen.size !== 1)\n                    throw new Error("LEGACY_HISTORY_USER_BOUNDARY_INVALID");\n            }\n            else if (userCount !== 1)\n                throw new Error("LEGACY_HISTORY_USER_MISSING");\n            if (native.role === "assistant") {\n                if (pending.size)\n                    throw new Error("LEGACY_HISTORY_TOOL_RESULT_MISSING");\n                endedAssistant = true;\n                for (const block of native.content)\n                    if (block.type === "toolCall") {\n                        if (called.has(block.id))\n                            throw new Error("LEGACY_HISTORY_DUPLICATE_CALL");\n                        called.add(block.id);\n                        pending.set(block.id, block.name);\n                    }\n            }\n            else if (native.role === "toolResult") {\n                if (pending.get(native.toolCallId) !== native.toolName)\n                    throw new Error("LEGACY_HISTORY_ORPHAN_RESULT");\n                pending.delete(native.toolCallId);\n            }\n            messages.push(message);\n        }\n        if (userCount !== 1 || pending.size)\n            throw new Error("LEGACY_HISTORY_INCOMPLETE");\n        if (!endedAssistant && run.status !== "cancelled")\n            throw new Error("LEGACY_HISTORY_INCOMPLETE");\n        if (run.status === "cancelled") {\n            if (!endedAssistant)\n                incompleteCancelledRuns.push(run.runId);\n            messages.push({\n                role: "custom",\n                customType: "himawari.turn_aborted",\n                display: false,\n                timestamp,\n                content: "<turn_aborted>The user interrupted this turn. The legacy legacyRecord may omit partial output. Recorded tool results remain authoritative; cancellation does not undo side effects. Handle the new request and resume earlier work only when requested.</turn_aborted>",\n            });\n        }\n        coveredRunIds.push(run.runId);\n    }\n    return {\n        messages,\n        coveredRunIds,\n        duplicateMessages,\n        repairedUsageTotals,\n        incompleteCancelledRuns,\n    };\n}\n\nconst threadId=\'thread:67f83b5e-f5ab-4313-9efd-94f30e4d97b3\';\nconst runs=db.prepare(`SELECT runs.id, runs.status, MIN(m.sequence) AS sequence FROM runs JOIN thread_messages m ON m.run_id=runs.id AND m.owner_id=runs.owner_id AND m.agent_id=runs.agent_id WHERE runs.owner_id=? AND runs.agent_id=? AND runs.thread_id=? AND m.role=\'owner\' GROUP BY runs.id ORDER BY sequence LIMIT 51`).all(config.ownerId,config.agentId,threadId);\nassert(runs.length>0 && runs.length<=50,\'AUDIT_RUN_BOUND\');\nconst reports=[], legacyRuns=[];\nfor(const run of runs){\n const events=db.prepare("SELECT sequence,event_type,payload_ref FROM trace_events WHERE owner_id=? AND agent_id=? AND run_id=? AND event_type=\'runtime.message\' ORDER BY sequence LIMIT 2001").all(config.ownerId,config.agentId,run.id);\n assert(events.length<=2000,\'AUDIT_EVENT_BOUND\');\n const messages=[],finalizedMessages=[],calls=new Set(),results=new Set(); let partial=0;\n for(const event of events){\n  const envelope=await payload(event.payload_ref); assert.equal(envelope.runId,run.id,\'AUDIT_EVENT_SCOPE\');\n  if(envelope.phase!==\'ended\'){partial++;continue;}\n  const artifact=db.prepare("SELECT content_digest FROM run_payload_artifacts WHERE owner_id=? AND agent_id=? AND run_id=? AND purpose=\'trace\' AND payload_ref=?").get(config.ownerId,config.agentId,run.id,envelope.payloadRef);\n  assert(artifact,\'AUDIT_MESSAGE_SCOPE\');\n  const message=await payload(envelope.payloadRef);\n  assert.equal(message.role,envelope.role,\'AUDIT_MESSAGE_ROLE\');\n  finalizedMessages.push(message);\n  const content=JSON.stringify(message);\n  const nativeCalls=Array.isArray(message.content)?message.content.filter(x=>x.type===\'toolCall\'):[];\n  for(const call of nativeCalls)calls.add(call.id);\n  if(message.role===\'toolResult\')results.add(message.toolCallId);\n  messages.push({traceSequence:event.sequence,payloadRef:envelope.payloadRef,digest:artifact.content_digest,role:message.role,stopReason:message.stopReason??null,redacted:content.includes(\'[REDACTED\'),localUnwind:content.includes(\'RUNTIME_TOOL_SUSPENDED\'),toolCalls:nativeCalls.length,hasProviderIdentity:[\'provider\',\'api\',\'model\'].every(k=>typeof message[k]===\'string\')});\n }\n assert(["completed","cancelled","failed"].includes(run.status),"AUDIT_RUN_ACTIVE");\n legacyRuns.push({runId:run.id,status:run.status,finalizedMessages});\n reports.push({runId:run.id,status:run.status,sequence:run.sequence,partialEvents:partial,finalMessages:messages,unpairedCallCount:[...calls].filter(x=>!results.has(x)).length,orphanResultCount:[...results].filter(x=>!calls.has(x)).length});\n}\n\nconst previousAudit=JSON.parse(await readFile(root+\'/qualifications/2026-09-11-protected/attempt-v5/native-history-audit.json\',\'utf8\'));\nassert.deepEqual(reports,previousAudit.runs,\'AUDIT_SOURCE_CHANGED\');\nconst candidate=qualifyLegacyPiHistory(legacyRuns);\nconst head=db.prepare(\'SELECT message_watermark,revision FROM threads WHERE id=? AND owner_id=? AND agent_id=?\').get(threadId,config.ownerId,config.agentId);\nassert(head,\'AUDIT_THREAD_MISSING\');\nconst importedAt=new Date().toISOString();\nconst value={version:\'himawari.legacy-history-import.v1\',ownerId:config.ownerId,agentId:config.agentId,threadId,head,source:reports,history:candidate};\nconst encoded=new TextEncoder().encode(JSON.stringify(value));assert(encoded.length<4*1024*1024,\'AUDIT_CANDIDATE_TOO_LARGE\');\nconst sealed=await protector.protect({ownerId:config.ownerId,agentId:config.agentId,ref:\'legacy-native-history-candidate-20260911\',dataClassification:\'private\',contentType:\'application/json\',plaintext:encoded,createdAt:importedAt});\ndb.close();\nconsole.log(JSON.stringify({at:importedAt,scope:\'qualified encrypted legacy import candidate; product database remains unchanged\',threadId,runs:reports,duplicateMessages:candidate.duplicateMessages,repairedUsageTotals:candidate.repairedUsageTotals,incompleteCancelledRuns:candidate.incompleteCancelledRuns,messageCount:candidate.messages.length,candidate:{...sealed,ciphertext:Buffer.from(sealed.ciphertext).toString(\'base64\')}}));\n'
command=['/usr/bin/systemd-run','--quiet','--wait','--pipe','--collect',
 '--property=User=himawari','--property=Group=himawari',
 '--property=RuntimeMaxSec=120','--property=WorkingDirectory=/',
 '--property=NoNewPrivileges=yes','--property=PrivateNetwork=yes',
 '--property=ProtectSystem=strict','--property=PrivateTmp=yes',
 '--property=TemporaryFileSystem=/data/hermes:ro,mode=0755',
 '--property=BindReadOnlyPaths=/data/hermes/himawari',
 str(root/'releases/2026-09-11-control-center/lib/himawari-agent/pi-tools/bin/node'),'--input-type=module']
result=subprocess.run(command,input=NODE_SOURCE,text=True,capture_output=True,timeout=150)
if result.returncode:
 # Do not echo arbitrary process output that could contain private data.
 report={'passed':False,'exitCode':result.returncode,'errorLines':[line[:240] for line in result.stderr.splitlines() if line.startswith(('Error:','AssertionError','  code:'))][:4]}
else:
 report=json.loads(result.stdout)
 report['passed']=True
 assert 0 < len(report['runs']) <= 50
if 'candidate' in report:
 candidate_path=output.parent/'native-history-import-candidate.json'
 fd=os.open(candidate_path,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
 with os.fdopen(fd,'w') as handle:json.dump(report.pop('candidate'),handle)
 report['candidatePath']=str(candidate_path)
with output.open('x') as handle:json.dump(report,handle,ensure_ascii=False,indent=2)
output.chmod(0o644)
print('Native history audit written: '+str(output))
